/**
 * =============================================================================
 * KS-780 — organisation-id normalisation has ONE implementation, and it is this one
 * =============================================================================
 * Two behaviourally identical copies of the normaliser existed in two layers
 * (originate's `services/orgId.ts` and a private `normOrgId` inside the shared
 * revoke policy), and neither could witness the other drifting. The move puts
 * the implementation here and makes originate a re-export.
 *
 * WHAT THIS FILE PINS. Not "the function exists" — the four properties every
 * caller relies on, each as its own cell so a drift reads by name, plus the
 * structural claim that the revoke policy really does go through THIS function
 * (a re-introduced private copy would leave every property cell green while
 * the policy quietly diverged — the exact defect the ticket describes). The
 * originate side of the same claim lives in
 * `services/originate/src/__tests__/ks780-org-id-is-the-shared-implementation.test.ts`.
 *
 * RED-PROOF (the ticket's own done-means): one character in the implementation
 * — drop `.toLowerCase()` — reds P2 here AND the originate ks597 comparison
 * cells AND the policy's case-insensitive cell, from ONE edit. That is what "one
 * implementation" buys and what two copies could never show.
 * =============================================================================
 */

import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { normaliseOrgId, decideKeyRevoke } from '../index';
import { normaliseOrgId as fromModule } from '../security/orgId';

// Hex LETTERS on purpose: an all-digit uuid upper-cases to itself and a case
// cell against it proves nothing — measured, the tamper below left it green.
const ORG = 'a1b2c3d4-e5f6-4a7b-8c9d-ef0123456789';

describe('KS-780 — normaliseOrgId, the four properties', () => {
  it('P1 TRIM — surrounding whitespace is not identity', () => {
    expect(normaliseOrgId(`  ${ORG}\t`)).toBe(ORG);
  });

  it('P2 CASE — a differently-cased rendering of the same uuid is the SAME organisation', () => {
    expect(normaliseOrgId(ORG.toUpperCase())).toBe(ORG);
    // And the control: a genuinely different id stays different.
    expect(normaliseOrgId('b2c3d4e5-f6a7-4b8c-9d0e-f01234567890')).not.toBe(ORG);
  });

  it('P3 BLANK IS ABSENT — empty and whitespace-only are null, not a distinct id', () => {
    expect(normaliseOrgId('')).toBeNull();
    expect(normaliseOrgId('   ')).toBeNull();
    expect(normaliseOrgId('\t\n')).toBeNull();
  });

  it('P4 NON-STRING IS ABSENT — null, undefined and a non-string value are null', () => {
    expect(normaliseOrgId(null)).toBeNull();
    expect(normaliseOrgId(undefined)).toBeNull();
    expect(normaliseOrgId(42 as unknown as string)).toBeNull();
  });
});

describe('KS-780 — one implementation, structurally', () => {
  it('S1 the package export IS the module function (identity, not a copy)', () => {
    expect(normaliseOrgId).toBe(fromModule);
  });

  it('S2 the revoke policy has NO private normaliser left — its source names the shared one', () => {
    // Read the source, not the runtime: a re-introduced private copy would be
    // invisible to every behavioural cell above while the policy drifted.
    const src = readFileSync(join(__dirname, '..', 'security', 'keyRevokePolicy.ts'), 'utf8');
    const definitions = src
      .split('\n')
      .filter((l) => /^\s*(export\s+)?(function|const)\s+norm(alise)?OrgId\b/.test(l));
    expect(definitions, 'a second definition of the normaliser inside the policy').toEqual([]);
    expect(src).toMatch(/import \{ normaliseOrgId \} from '\.\/orgId';/);
    expect(src.match(/normaliseOrgId\(/g)?.length, 'the org arm calls it twice — target and caller').toBe(2);
  });

  it('S3 the policy really goes THROUGH it — a cased claim on a cased key is the same organisation', () => {
    // The behavioural half of S2: if the policy compared raw strings, an
    // upper-cased caller claim would read as a sibling organisation and refuse.
    const decision = decideKeyRevoke(
      { role: 'ISSUER_ADMIN', tenantId: 't', organizationId: ORG.toUpperCase() },
      { id: 'k', tenantId: 't', organizationId: ` ${ORG} ` },
    );
    expect(decision).toEqual({ allow: true, reason: 'same-organisation' });
  });
});
